import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 신규 입력 행의 마감 상태는 '신청' 고정값이다.
const INITIAL_CLOSING_STATUS = '신청';

interface ErrorRow {
  rowNo: number;
  dailyWorkerId: string;
  reason: string;
}

interface ValidRow {
  rowNo: number;
  workerId: string;
  workDays: string;
  payAmount: string;
  withholdingTax: string | null;
}

function validDate(text: string): boolean {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!m) {
    return false;
  }
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  if (month < 1 || month > 12 || day < 1) {
    return false;
  }
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day <= days[month - 1];
}

function textOf(value: unknown): string {
  if (typeof value === 'number') {
    return String(value);
  }
  if (typeof value === 'string') {
    return value.trim();
  }
  return '';
}

@Controller('api/v1')
export class FnSfr02114Controller {
  @Post('/daily-payrolls/bulk-create')
  @HttpCode(200)
  async bulkCreateDailyPayrolls(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const payDate = data['payDate'];
    if (typeof payDate !== 'string' || !validDate(payDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 지급일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const rows = data['rows'];
    if (!Array.isArray(rows) || rows.length === 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '입력할 사원별 급여 행이 없습니다.');
    }

    return transaction(async (db) => {
      const errorRows: ErrorRow[] = [];
      const validRows: ValidRow[] = [];
      const seen = new Set<string>();

      // 형식 오류 행은 사유와 함께 모으고 정상 행만 반영한다.
      for (let i = 0; i < rows.length; i++) {
        const rowNo = i + 1;
        const item: unknown = rows[i];
        if (item === null || typeof item !== 'object' || Array.isArray(item)) {
          errorRows.push({ rowNo, dailyWorkerId: '', reason: '행 형식이 올바르지 않습니다.' });
          continue;
        }
        const r = item as Record<string, unknown>;
        const workerId = textOf(r['dailyWorkerId']);
        const workDays = textOf(r['workDays']);
        const payAmount = textOf(r['payAmount']);
        const taxText = textOf(r['withholdingTax']);
        let reason = '';
        if (!/^\d+$/.test(workerId)) {
          reason = '일용직 사원이 올바르지 않습니다.';
        } else if (!/^\d+$/.test(workDays)) {
          reason = '근무일수는 0 이상의 정수여야 합니다.';
        } else if (!/^\d+(\.\d{1,2})?$/.test(payAmount)) {
          reason = '지급 금액은 0 이상의 숫자(소수 2자리까지)여야 합니다.';
        } else if (taxText !== '' && !/^\d+(\.\d{1,2})?$/.test(taxText)) {
          reason = '원천징수세액은 0 이상의 숫자(소수 2자리까지)여야 합니다.';
        } else if (seen.has(workerId)) {
          reason = '같은 일용직 사원이 중복 입력되었습니다.';
        }
        if (reason !== '') {
          errorRows.push({ rowNo, dailyWorkerId: workerId, reason });
          continue;
        }
        seen.add(workerId);
        validRows.push({
          rowNo,
          workerId,
          workDays,
          payAmount,
          withholdingTax: taxText === '' ? null : taxText,
        });
      }

      // 쓰기 전에 사원 존재와 마감 여부를 먼저 확인한다.
      const existingIds = new Map<string, string>();
      for (const row of validRows) {
        const workers = await db.query(
          'SELECT daily_worker_id AS "dailyWorkerId" FROM daily_worker WHERE daily_worker_id = CAST(:workerId AS bigint)',
          { workerId: row.workerId },
        );
        if (workers.length === 0) {
          throw new ApiError(404, 'DAILY_WORKER_NOT_FOUND', '일용직 사원을 찾을 수 없습니다.');
        }
        const existing = await db.query(
          'SELECT daily_payroll_id AS "dailyPayrollId", closing_status AS "closingStatus" FROM daily_payroll WHERE daily_worker_id = CAST(:workerId AS bigint) AND pay_date = CAST(:payDate AS date)',
          { workerId: row.workerId, payDate },
        );
        if (existing.length > 0) {
          if (existing[0]['closingStatus'] === '마감') {
            throw new ApiError(409, 'DAILY_PAYROLL_CLOSED', '마감된 일용직 급여는 일괄 입력으로 덮어쓸 수 없습니다.');
          }
          existingIds.set(row.workerId, String(existing[0]['dailyPayrollId']));
        }
      }

      let savedCount = 0;
      for (const row of validRows) {
        const payrollId = existingIds.get(row.workerId);
        if (payrollId !== undefined) {
          await db.execute(
            'UPDATE daily_payroll SET work_days = CAST(:workDays AS integer), pay_amount = CAST(:payAmount AS numeric), withholding_tax = COALESCE(CAST(:tax AS numeric), withholding_tax), updated_at = now() WHERE daily_payroll_id = CAST(:payrollId AS bigint)',
            { workDays: row.workDays, payAmount: row.payAmount, tax: row.withholdingTax, payrollId },
          );
        } else {
          await db.query(
            'INSERT INTO daily_payroll (daily_worker_id, pay_date, work_days, pay_amount, withholding_tax, closing_status, created_at, updated_at) VALUES (CAST(:workerId AS bigint), CAST(:payDate AS date), CAST(:workDays AS integer), CAST(:payAmount AS numeric), CAST(:tax AS numeric), :status, now(), now()) RETURNING daily_payroll_id AS "dailyPayrollId"',
            {
              workerId: row.workerId,
              payDate,
              workDays: row.workDays,
              payAmount: row.payAmount,
              tax: row.withholdingTax,
              status: INITIAL_CLOSING_STATUS,
            },
          );
        }
        savedCount += 1;
      }

      return { savedCount, errorRows };
    });
  }
}

