import { useState } from 'react';
import {
  call,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  RefName,
} from '../kit';
import type { PageProps, Row } from '../kit';

interface InputRow {
  dailyWorkerId: number | string;
  workDays: number | string;
  payAmount: number | string;
  withholdingTax: number | string;
}

const emptyRow = (): InputRow => ({
  dailyWorkerId: '',
  workDays: '',
  payAmount: '',
  withholdingTax: '',
});

export default function FnSfr02114Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [payDate, setPayDate] = useState('');
  const [inputs, setInputs] = useState<InputRow[]>([emptyRow()]);
  const [processed, setProcessed] = useState<Row[]>([]);
  const [errors, setErrors] = useState<Row[]>([]);
  const [savedTotal, setSavedTotal] = useState(0);

  const change = (index: number, patch: Partial<InputRow>) => {
    setInputs(inputs.map((r, i) => (i === index ? { ...r, ...patch } : r)));
  };

  const openDrawer = () => {
    setPayDate('');
    setInputs([emptyRow()]);
    setOpen(true);
  };

  const submit = async () => {
    if (payDate === '') {
      throw new Error('급여 지급일을 입력해 주세요.');
    }
    for (const r of inputs) {
      if (r.dailyWorkerId === '' || r.workDays === '' || r.payAmount === '') {
        throw new Error('모든 행에 일용직 사원, 근무일수, 지급 금액을 입력해 주세요.');
      }
    }
    const body: Row = {
      payDate,
      rows: inputs.map((r) => ({
        dailyWorkerId: r.dailyWorkerId,
        workDays: r.workDays,
        payAmount: r.payAmount,
        withholdingTax: r.withholdingTax === '' ? null : r.withholdingTax,
      })),
    };
    const result = await call<{ savedCount: number; errorRows: Row[] }>(
      'POST',
      '/daily-payrolls/bulk-create',
      role,
      body,
    );
    const failedNos = new Set(result.errorRows.map((e) => Number(e['rowNo'])));
    const done: Row[] = inputs
      .map((r, i) => ({ ...r, payDate, rowNo: i + 1 }) as Row)
      .filter((r) => !failedNos.has(Number(r['rowNo'])));
    setProcessed([...done, ...processed]);
    setErrors(result.errorRows);
    setSavedTotal(savedTotal + result.savedCount);
    setOpen(false);
    notify('일용직 급여 ' + result.savedCount + '건을 반영했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>반영 행</h2>
        <Num value={savedTotal} />
      </section>
      <section className="box span-4">
        <h2>오류 행</h2>
        <Num value={errors.length} />
      </section>
      <section className="box span-4">
        <h2>일괄 입력</h2>
        <button type="button" onClick={openDrawer}>급여 일괄 입력</button>
      </section>
      <section className="box span-8">
        <h2>입력 결과</h2>
        <Band total={processed.length} />
        <DataTable
          rows={processed}
          empty="반영된 급여가 없습니다."
          columns={[
            { key: 'payDate', label: '급여 지급일', render: (r) => <DateText value={r['payDate']} /> },
            {
              key: 'dailyWorkerId',
              label: '일용직 사원',
              render: (r) => <RefName table="daily_worker" role={role} value={r['dailyWorkerId']} />,
            },
            { key: 'workDays', label: '근무일수', render: (r) => <Num value={r['workDays']} /> },
            { key: 'payAmount', label: '지급 금액', render: (r) => <Num value={r['payAmount']} /> },
            { key: 'withholdingTax', label: '원천징수세액', render: (r) => <Num value={r['withholdingTax']} /> },
          ]}
        />
      </section>
      <section className="box span-4">
        <h2>오류 행</h2>
        <DataTable
          rows={errors}
          empty="오류 행이 없습니다."
          columns={[
            { key: 'rowNo', label: '행 번호' },
            { key: 'reason', label: '사유' },
          ]}
        />
      </section>
      {open && (
        <Drawer title="일용직 급여 일괄 입력" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="일괄 입력" note="오류 행은 사유와 함께 안내하고 정상 행만 반영합니다.">
            <Field label="급여 지급일" required>
              <DateInput value={payDate} onChange={setPayDate} />
            </Field>
            {inputs.map((r, i) => (
              <div key={i}>
                <Field label={'일용직 사원 ' + (i + 1)} required>
                  <LookupSelect
                    table="daily_worker"
                    role={role}
                    value={r.dailyWorkerId}
                    onChange={(v) => change(i, { dailyWorkerId: v })}
                  />
                </Field>
                <Field label="근무일수" required>
                  <NumberInput value={r.workDays} onChange={(v) => change(i, { workDays: v })} />
                </Field>
                <Field label="지급 금액" required>
                  <NumberInput value={r.payAmount} onChange={(v) => change(i, { payAmount: v })} />
                </Field>
                <Field label="원천징수세액" hint="비우면 저장 후 산출됩니다.">
                  <NumberInput value={r.withholdingTax} onChange={(v) => change(i, { withholdingTax: v })} />
                </Field>
                {inputs.length > 1 && (
                  <button type="button" onClick={() => setInputs(inputs.filter((_, j) => j !== i))}>
                    행 삭제
                  </button>
                )}
              </div>
            ))}
            <button type="button" onClick={() => setInputs([...inputs, emptyRow()])}>행 추가</button>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
